intro x
have : x ∈ s ∩ t ∪ s ∩ u := by
  cases x with
  | inl a => exact ⟨a, by { rw ← Set.in_inl; exact ⟨a, by { rw ← Set.in_inl; exact ⟨a, by { linarith [Set.mem_inter, Set.mem_union] } end } end } end }
  | inr b => exact ⟨b, by { rw ← Set.in_inr; exact ⟨b, by { rw ← Set.in_inr; exact ⟨b, by { linarith [Set.mem_inter, Set.mem_union] } end } end } end }
cases this with
| ⟨a, ⟨a₁, a₂⟩⟩ => exact ⟨a, by { rw ← Set.in_inter; exact ⟨a₁, by { rw ← Set.in_union; exact ⟨a₁, by { linarith [Set.mem_inter, Set.mem_inter] } end } end } end }
| ⟨a, ⟨a₃, a₄⟩⟩ => exact ⟨a, by { rw ← Set.in_inter; exact ⟨a₄, by { rw ← Set.in_union; exact ⟨a₄, by { linarith [Set.mem_inter, Set.mem_inter] } end } end } end }

intros x h
have h1 : x ∈ s ∩ t ∪ s ∩ u := h
cases h1 with h2 h3
  { cases h2 with h4 h5
    { exact ⟨h4, h5, or.inl h3⟩ }
  }
  { cases h3 with h6 h7
    { exact ⟨h6, h7, or.inr h3⟩ }
  }
· rw [Set.mem_inter, Set.mem_union]
  exact ⟨h4, or.elim h3 h5 h7⟩
